package pro.aanba.tv;
import org.junit.Test;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import static org.junit.Assert.*;
public class LibraryDataTest {
 String fixture(String name)throws Exception{return new String(getClass().getResourceAsStream("/"+name).readAllBytes(),StandardCharsets.UTF_8);}
 Match match(String prefix,String id){return new Match("schedule-"+id,"A","B","GSW","PHX","NBA","finished","https://vkvideo.ru/"+prefix+"-55574239_"+id,"",Instant.parse("2026-10-25T02:00:00Z").toEpochMilli());}
 @Test public void recordingHistorySurvivesReloadAndDifferentScheduleId(){WatchHistory h=new WatchHistory("[]");Match m=match("live","456428310");assertTrue(h.save(WatchHistory.key(m),1200,10000,123));WatchHistory restored=new WatchHistory(h.serialize());WatchHistory.Entry e=restored.get(match("video","456428310"));assertNotNull(e);assertTrue(e.resumable());assertEquals(1200,restored.restore(e,0,10000),.01);assertNull(restored.get(match("video","456428311")));assertEquals(.12,e.fraction(),.0001);}
 @Test public void completedRecordStartsFromBeginning(){WatchHistory h=new WatchHistory("[]");h.save("x",9990,10000,1);WatchHistory.Entry e=h.entries.get("x");assertTrue(e.completed);assertFalse(e.resumable());assertEquals(0,h.restore(e,0,10000),0);}
 @Test public void badPositionsCannotOverwriteGoodHistory(){WatchHistory h=new WatchHistory("[]");h.save("x",500,1000,1);for(double bad:new double[]{Double.NaN,Double.POSITIVE_INFINITY,-1,1001})assertFalse(h.save("x",bad,1000,2));assertFalse(h.save("",1,1000,2));assertFalse(h.save("y",5,12,2));assertEquals(500,h.entries.get("x").seconds,0);}
 @Test public void resumeClampsRangeAndRejectsDifferentDuration(){WatchHistory h=new WatchHistory("[]");h.save("x",500,10000,1);WatchHistory.Entry e=h.entries.get("x");assertEquals(600,h.restore(e,600,10000),0);assertEquals(-1,h.restore(e,0,2000),0);assertEquals(-1,h.restore(e,10,10),0);assertEquals(-1,h.restore(e,0,Double.NaN),0);}
 @Test public void boundedHistoryPrunesOldestAndCorruptJsonIsSafe(){WatchHistory h=new WatchHistory("invalid");assertTrue(h.entries.isEmpty());for(int i=0;i<65;i++)h.save("id"+i,100,1000,i);assertEquals(60,h.entries.size());assertFalse(h.entries.containsKey("id0"));assertTrue(h.entries.containsKey("id64"));assertEquals(60,new WatchHistory(h.serialize()).entries.size());}
 @Test public void favoritesAreLeagueSpecificAndCanonical(){assertEquals(UserLibrary.teamKey("nba","GS"),UserLibrary.teamKey("NBA","GSW"));assertNotEquals(UserLibrary.teamKey("nba","GS"),UserLibrary.teamKey("wnba","GS"));}
 @Test public void officialYoutubeFeedHasActualTitlesAndLongFormFeatured()throws Exception{YoutubeFeed feed=YoutubeFeed.parse(fixture("youtube-feed.xml"),1);assertEquals(15,feed.videos.size());assertEquals(1,feed.fetchedAt);assertTrue(feed.videos.stream().anyMatch(v->v.id.equals("g68Rh2qeuf4")&&v.title.contains("ПРЕВЬЮ")));assertEquals(3,feed.featured().size());assertTrue(feed.featured().stream().anyMatch(v->v.id.equals("g68Rh2qeuf4")));long before=Long.MAX_VALUE;for(YoutubeFeed.Video v:feed.videos){assertTrue(v.watchUrl().matches("https://www\\.youtube\\.com/watch\\?v=[A-Za-z0-9_-]{11}"));assertTrue(v.published<=before);before=v.published;}}
 @Test public void youtubeRejectsOtherChannelAndXmlEntities()throws Exception{String xml=fixture("youtube-feed.xml");try{YoutubeFeed.parse(xml.replace("-GILc1ZMxtDAyIATn6de5Q","other-channel"),1);fail();}catch(java.io.IOException expected){}try{YoutubeFeed.parse("<!DOCTYPE foo [ <!ENTITY bar SYSTEM 'file:///etc/passwd'> ]>"+xml,1);fail();}catch(java.io.IOException expected){}}
 @Test public void missingThumbnailFallsBackToCanonicalVideoImage()throws Exception{String xml=fixture("youtube-feed.xml").replaceAll("https://i[0-9]?.ytimg.com/vi/[^\"]+","https://evil.example/track");for(YoutubeFeed.Video v:YoutubeFeed.parse(xml,1).videos)assertTrue(v.thumbnail.startsWith("https://i.ytimg.com/vi/"));}
 @Test public void seasonStatsUseTotalsForTrueShootingNotAveragePercentages()throws Exception{SeasonStats s=SeasonStats.parse(fixture("team-stats.json"),1);assertEquals(2027,s.year);assertEquals("MIN",s.code);assertEquals("16",s.teamId);assertEquals(100*(88+.5*35)/196,s.numbers.get("efgPct"),.0001);assertEquals(100*246/(2*(196+.44*59)),s.numbers.get("trueShootingPct"),.0001);assertEquals(100*87d/196,s.numbers.get("threeAttemptRate"),.0001);assertEquals(100*59d/196,s.numbers.get("ftAttemptRate"),.0001);}
 @Test public void zeroOrMissingAttemptsDoNotCreateMadeUpPercentages()throws Exception{JSONObject root=new JSONObject(fixture("team-stats.json"));JSONArray categories=root.getJSONObject("results").getJSONObject("stats").getJSONArray("categories");for(int i=0;i<categories.length();i++){JSONArray stats=categories.getJSONObject(i).getJSONArray("stats");for(int j=0;j<stats.length();j++)if(stats.getJSONObject(j).getString("name").equals("fieldGoalsAttempted"))stats.getJSONObject(j).put("value",0);}assertEquals("—",SeasonStats.parse(root.toString(),1).value("efgPct"));root.getJSONObject("results").getJSONObject("stats").put("categories",new JSONArray());assertEquals("—",SeasonStats.parse(root.toString(),1).value("trueShootingPct"));}
 @Test public void requestedHistoricalSeasonWinsOverCurrentMetadata()throws Exception{JSONObject root=new JSONObject(fixture("team-stats.json"));root.put("requestedSeason",new JSONObject().put("year",2024).put("type",3).put("displayName","2023-24"));SeasonStats s=SeasonStats.parse(root.toString(),1);assertEquals(2024,s.year);assertEquals(3,s.type);assertEquals("2023-24",s.season);}
 @Test public void nextWeeksScheduleIsMatchedByNewDateNotThisWeeksGame()throws Exception{Match current=match("live","456428310");JSONObject future=current.toJson();future.put("id","next-week-new-id");long next=current.start+7*86400000L;future.put("datetime",Instant.ofEpochMilli(next).toString());List<Match> parsed=ScheduleParser.parse(new JSONArray().put(future).toString());assertEquals(1,parsed.size());Match m=parsed.get(0);assertEquals(next,m.start);Score old=Score.demo(current);assertFalse(old.matches(m));Score fresh=Score.demo(m);assertTrue(fresh.matches(m));assertEquals("20261031",m.espnDate());}
}
